WITH latest_match AS (SELECT s.*, top1.sale_date, top1.store_sale_units FROM products s JOIN LATERAL (SELECT c.sale_date, c.units AS store_sale_units FROM store_sales c WHERE c.product_id = s.id ORDER BY c.units DESC, c.id DESC LIMIT 1) top1 ON TRUE) SELECT s.id, s.product_name, s.category, s.brand, s.price, s.cost, s.launch_date, s.tags, s.supplier_id, CASE WHEN product_name RLIKE '^(wireless mouse|Desk Lamp)$' THEN 'CORE' WHEN product_name RLIKE '^(Laptop Pro 14|USB-C Hub)$' THEN 'OTHER_ZONE' ELSE 'PRIORITY' END AS product_name_zone, (SELECT SUM(x.stock_qty) FROM products x WHERE x.supplier_id = s.supplier_id) AS sum_product_stock_qty FROM latest_match s ORDER BY price;
